$$
\begin{aligned}
\bar{w}_i^\mu &= \sum_{\mu_*=1}^{P^*} x_i^{*\mu_*} \sum_{y=0}^C q_y^{*\mu_*} \sigma_\mu(\beta m^{\mu_*}(\mathbf{x}^*,\mathbf{w}) + \log[\mathbf{p}_y]) \\
w_i^\mu &= \frac{\bar{w}_i^\mu}{\sqrt{\sum_j [\bar{w}_j^\mu]^2}} \\
\bar{p}_y^\gamma &= \sum_{\mu_*=1}^{P^*} q_y^{*\mu_*} \sigma_\gamma(\beta m^{\mu_*}(\mathbf{x}^*,\mathbf{w}) + \log[\mathbf{p}_y]) \\
p_y^\gamma &= \frac{\bar{p}_y^\gamma}{\zeta_y^\gamma(\overline{\mathbf{p}}; p_{\mathbf{h}})}
\end{aligned}
$$
where $\sigma_\gamma$ is the softmax function and $\zeta$ is a normalization constant.
